const expectedToken = $env.N8N_SERVICE_TOKEN || 'campusdesk-super-secret-service-token-2026';
const headers = $input.first().json.headers || {};
const token = headers['x-service-token'] || headers['X-Service-Token'];

if (!token || token !== expectedToken) {
  return [{ json: { authorized: false, error: 'Unauthorized: Invalid or missing X-Service-Token' } }];
}

const body = $input.first().json.body || {};
const queryText = body.prompt || body.queryText || (body.title + ': ' + body.category);

return [{
  json: {
    authorized: true,
    queryId: body.queryId,
    ticketId: body.ticketId,
    category: body.category || 'General',
    title: body.title || 'Consulta',
    queryText: queryText
  }
}];

const qdrantResults = $input.first().json.result || [];
const prevData = $('Validar Token y Parametros').first().json;

if (qdrantResults.length === 0) {
  return [{
    json: {
      hasMatches: false,
      queryId: prevData.queryId,
      queryText: prevData.queryText,
      category: prevData.category,
      title: prevData.title,
      candidates: []
    }
  }];
}

const candidates = qdrantResults.map(r => ({
  articleId: r.payload.articleId || r.payload.articulo_id || r.id,
  title: r.payload.title || r.payload.titulo || '',
  category: r.payload.category || r.payload.categoria || '',
  content: r.payload.content || r.payload.contenido || '',
  version: r.payload.version || 1,
  score: r.score
}));

return [{
  json: {
    hasMatches: true,
    queryId: prevData.queryId,
    queryText: prevData.queryText,
    category: prevData.category,
    title: prevData.title,
    candidates: candidates
  }
}];

const eligibilityResponse = $input.first().json;
const eligibleMap = eligibilityResponse.eligible || {};
const processData = $('Procesar Coincidencias').first().json;
const candidates = processData.candidates || [];

const validSources = candidates.filter(c => eligibleMap[c.articleId] === true);

if (validSources.length === 0) {
  return [{
    json: {
      hasValidSources: false,
      queryId: processData.queryId
    }
  }];
}

let contextText = '';
validSources.forEach((src, idx) => {
  contextText += `--- FUENTE ${idx + 1}: ${src.title} (ID: ${src.articleId}, Categoría: ${src.category}) ---\n${src.content}\n\n`;
});

return [{
  json: {
    hasValidSources: true,
    queryId: processData.queryId,
    queryText: processData.queryText,
    category: processData.category,
    title: processData.title,
    validSources: validSources,
    contextText: contextText
  }
}];

const responseData = $input.first().json;
const filterData = $('Filtrar Fuentes Elegibles').first().json;

const contentStr = responseData.choices[0].message.content.trim();
let parsed = {};
try {
  const cleaned = contentStr.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    summary: contentStr,
    steps: [],
    recommendations: null
  };
}

const sourcesFormatted = (filterData.validSources || []).map(src => ({
  articleId: src.articleId,
  title: src.title,
  similarityScore: src.score,
  version: src.version
}));

return [{
  json: {
    queryId: filterData.queryId,
    status: 'ANSWERED',
    summary: parsed.summary || 'Solución sugerida por IA',
    steps: Array.isArray(parsed.steps) ? parsed.steps : [],
    recommendations: parsed.recommendations || null,
    sources: sourcesFormatted,
    modelName: 'google/gemini-2.5-flash'
  }
}];
